import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import fs from 'node:fs';
const require=createRequire(import.meta.url);
const {createAuthBoundary}=require('../../cloud/supabase/auth-boundary-v342.js');
const {createSyncSettingsUI}=require('../../cloud/sync-ui-v342.js');
let request=null,mode='success',calls=0;
const session={user:{id:'test-user',email:'learner@example.com'},access_token:'test-session-only'};
const client={auth:{getSession:async()=>({data:{session:null}}),onAuthStateChange:()=>({data:{subscription:{unsubscribe(){}}}}),signInWithOtp:async()=>({error:null}),signOut:async()=>({error:null}),verifyOtp:async(input)=>{
  calls++;request=input;
  if(mode==='error')return {error:{message:'invalid'}};
  if(mode==='throw')throw new Error('network');
  return {data:{session:mode==='missing'?null:session},error:null};
}}};
const auth=createAuthBoundary({client,redirectTo:'https://fe-quest.pages.dev/'});
await auth.initialize();
assert.equal((await auth.verifyEmailCode('learner@example.com','abc')).status,'invalid-code');
assert.equal(calls,0,'malformed code must not be sent');
mode='error';assert.equal((await auth.verifyEmailCode('learner@example.com','123456')).ok,false);
assert.equal(auth.snapshot().signedIn,false,'rejected code must not establish a session');
mode='missing';assert.equal((await auth.verifyEmailCode('learner@example.com','123456')).status,'session-missing');
mode='throw';assert.equal((await auth.verifyEmailCode('learner@example.com','123456')).ok,false);
mode='success';const success=await auth.verifyEmailCode(' LEARNER@example.com ','123456');
assert.equal(success.ok,true);assert.equal(auth.snapshot().userId,'test-user');
assert.deepEqual(request,{email:'learner@example.com',token:'123456',type:'email'});
assert.equal('accessToken' in success.snapshot,false,'public result must not expose tokens');
await auth.signOutThisDevice();assert.equal(auth.snapshot().signedIn,false);

let emailUsed=null,sendMode=true,verifyCalls=0,release;
const uiAuth={snapshot:()=>({initialized:true,signedIn:false}),sendMagicLink:async(email)=>sendMode?{ok:true,email}:{ok:false},verifyEmailCode:async(email)=>{emailUsed=email;verifyCalls++;return new Promise(resolve=>{release=resolve;});},signOutThisDevice:async()=>({ok:true})};
const controller={state:()=>({}),enableSync(){},syncNow(){},resolveConflict(){},disableSync(){}};
const ui=createSyncSettingsUI({authBoundary:uiAuth,controller,document:null});
assert.equal((await ui.verifyEmailCode('123456')).status,'email-required');
await ui.sendMagicLink('first@example.com');
sendMode=false;await ui.sendMagicLink('other@example.com');
const pending=ui.verifyEmailCode('123456');
assert.equal(emailUsed,'first@example.com','verify against the successful send recipient');
assert.equal((await ui.verifyEmailCode('123456')).status,'busy');assert.equal(verifyCalls,1,'double submit blocked');
release({ok:true});await pending;
assert.equal((await ui.verifyEmailCode('123456')).status,'email-required','successful verification clears pending recipient');
assert.ok(fs.readFileSync('index.html','utf8').includes('./assets/email-code-login-v1.js'));
assert.ok(fs.readFileSync('sw.js','utf8').includes('./assets/email-code-login-v1.js'));
console.log('PASS email-code validation, failed/successful sessions, recipient binding, duplicate submit, asset wiring');
